const entries = Object.entries(wordCount);
entries.sort((a, b) => {
  if (b[1] !== a[1]) {
    return b[1] - a[1]; // Count descending
  }
  return a[0].localeCompare(b[0]); // Alphabetically ascending
});

// Output
for (const [word, count] of entries) {
